// 辅助函数：格式化文本
function formatTextWithLineBreaks(text) {
    if (!text) return '';
    return text.replace(/\n/g, '<br>').replace(/▪/g, '• ');
}

// 渲染指定章节
function renderChapter(chapterId) {
    const container = document.getElementById('dynamicContent');
    const chapter = chaptersData[chapterId];
    if (!chapter) return;

    let html = `<div class="chapter-card">
                    <div class="chapter-title">${chapter.title}</div>`;
    
    chapter.sections.forEach(section => {
        html += `<div class="section-block">
                    <div class="section-sub">📌 ${section.subtitle}</div>
                    <div class="eng-text"><strong>📘 English:</strong><br>${formatTextWithLineBreaks(section.eng)}</div>
                    <div class="zh-text"><strong>📖 中文参考：</strong><br>${formatTextWithLineBreaks(section.zh)}</div>
                </div>`;
    });
    
    html += `</div>`;
    container.innerHTML = html;
}

// 高亮当前激活的导航项
function setActiveNav(activeId) {
    document.querySelectorAll('.nav-link').forEach(link => {
        const chap = link.getAttribute('data-chapter');
        if (chap === activeId) {
            link.classList.add('active');
        } else {
            link.classList.remove('active');
        }
    });
}

// 初始化：绑定点击事件、渲染默认章节
function init() {
    // 绑定所有导航链接的点击事件
    document.querySelectorAll('.nav-link').forEach(link => {
        link.addEventListener('click', (e) => {
            e.preventDefault();
            const chapterId = link.getAttribute('data-chapter');
            if (chapterId && chaptersData[chapterId]) {
                renderChapter(chapterId);
                setActiveNav(chapterId);
                window.location.hash = chapterId;
            }
        });
    });

    // 根据 hash 或默认显示第一章
    let initChapter = 'chapter1';
    if (window.location.hash && window.location.hash.length > 1) {
        const hashVal = window.location.hash.substring(1);
        if (chaptersData[hashVal]) initChapter = hashVal;
    }
    renderChapter(initChapter);
    setActiveNav(initChapter);
}

window.addEventListener('DOMContentLoaded', init);